import {PEOPLE,eraOf,filterPeople,pickPerson,makeChoices,matchesAnswer,calculateScore,yearLabel,lifeDates,ageAt,readStats,recordGame,STORE_KEY} from './core.js';
import {eras} from './people.js';
import {TheaterStage} from './stage.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const two=n=>String(n).padStart(2,'0');
let safeStorage;try{safeStorage=window.localStorage}catch{safeStorage={getItem:()=>null,setItem:()=>{throw Error('storage')}}}
let stats=readStats(safeStorage),era='all',region='all',currentView='home',game=null,stage,hero,portrait=null,portraitPerson=null;
let speed=1,sound=false,narration=false,audio=null,toastTimer=null,lastFrame=0,ambientClock=0,heroClock=0,heroIndex=0,archiveRegion='all',archiveEra='all',archiveUnlocked=false;
const DURATION=12.5;
const sceneNames={birth:'誕生',farewell:'終幕',journey:'旅立ち',voyage:'海の向こうへ',writing:'言葉の力',study:'学び',school:'学びの場',battle:'時代のうねり',laboratory:'探究',studio:'創作',music:'響き',palace:'転機',council:'決断',hospital:'いのち',night:'夜を越えて',exile:'試練',prison:'閉ざされた日々',peace:'未来へ',award:'光が届く',crowd:'人々と',speech:'声を届ける',stars:'見えない世界',space:'宇宙へ',flight:'空へ',telescope:'空を見上げる',map:'世界を描く',survey:'測る',fire:'試練',home:'日々',water:'出会い',machine:'仕組み',workshop:'ものづくり',factory:'産業',city:'街',pond:'自然',shore:'海辺',fossil:'太古',pyramid:'王国',castle:'城',temple:'祈り',training:'修練',cinema:'動き出す',motorcycle:'走る',bicycle:'走る',bus:'抵抗',perfume:'香り',electric:'電気',sunflowers:'色彩',tower:'表現',prism:'光',chart:'数字',island:'島'};
function notify(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3200)}
function persist(){try{safeStorage.setItem(STORE_KEY,JSON.stringify(stats))}catch{notify('このブラウザでは記録を保存できません。')}}
function updateCounts(){$('navCount').textContent=`${Object.keys(stats.records).length}/${PEOPLE.length}`}
function showView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));currentView=id;window.scrollTo({top:0,behavior:'instant'});$('archiveBtn').classList.toggle('active',id==='archive');if(id!=='theater')stopSpeech();if(id==='theater')requestAnimationFrame(()=>stage.resize());if(id==='home')requestAnimationFrame(()=>hero.resize())}
function updateFilters(){const pool=filterPeople(era,region);$('poolCount').textContent=`${pool.length}の物語`;$('startBtn').disabled=!pool.length;document.querySelectorAll('[data-region]').forEach(b=>b.classList.toggle('selected',b.dataset.region===region));$('eraOptions').innerHTML=eras.map(e=>{const n=filterPeople(e.id,region).length;return `<button class="era-option ${e.id===era?'selected':''}" data-era="${e.id}" aria-pressed="${e.id===era}" ${n?'':'disabled'}><strong>${e.label}</strong><small>${e.range}</small></button>`}).join('');$('eraOptions').querySelectorAll('button').forEach(b=>b.onclick=()=>{era=b.dataset.era;updateFilters()})}
function stopSpeech(){try{window.speechSynthesis?.cancel()}catch{}}
function speak(){stopSpeech();if(!narration||!game||game.paused||currentView!=='theater'||!window.speechSynthesis)return;const e=game.person.events[game.index];const u=new SpeechSynthesisUtterance(`${e.scene==='farewell'?(game.person.diedLabel||yearLabel(e.year)):(e.scene==='birth'?game.person.bornLabel||yearLabel(e.year):yearLabel(e.year))}。${e.title}。${e.text}`);u.lang='ja-JP';u.rate=.91;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('ja'));if(voice)u.voice=voice;speechSynthesis.speak(u)}
function tone(type='scene'){if(!sound||!audio)return;try{const notes=type==='correct'?[523.25,659.25,783.99]:type==='wrong'?[220,207.65]:[196,293.66,329.63];notes.forEach((f,i)=>{const osc=audio.createOscillator(),gain=audio.createGain(),start=audio.currentTime+i*.17;osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(type==='wrong'?.025:.035,start+.04);gain.gain.exponentialRampToValueAtTime(.0001,start+1.1);osc.connect(gain);gain.connect(audio.destination);osc.start(start);osc.stop(start+1.2)})}catch{}}
function setPaused(paused){if(!game)return;game.paused=paused;stage.frozen=paused;$('pauseBtn').textContent=paused?'▶':'Ⅱ';$('pauseBtn').setAttribute('aria-label',paused?'再生':'一時停止');if(paused)stopSpeech();else speak()}
function start(person=null){const selected=person||pickPerson(filterPeople(era,region),stats.records,stats.recent);if(!selected){notify('この条件の人物はまだいません。');return}stopSpeech();game={person:selected,index:0,elapsed:0,maxProgress:0,paused:false,correct:false,mistakes:0,usedChoices:false,hint:false,wrongNames:new Set(),options:makeChoices(selected),score:0,answeredAt:null,saved:false,guessPaused:false};$('correctBanner').hidden=true;$('guessBtn').textContent='名前がわかった →';$('guessPrompt').textContent='この人生、誰だろう。';$('guessSub').textContent='早く気づくほど、高得点。';$('guessBtn').onclick=openGuess;$('storyIndex').textContent=`AN UNKNOWN LIFE · NO. ${two(PEOPLE.indexOf(selected)+1)}`;$('pauseBtn').textContent='Ⅱ';$('pauseBtn').setAttribute('aria-label','一時停止');stage.frozen=false;if(portrait)portrait.observer.disconnect();portrait=null;portraitPerson=null;showView('theater');renderScene();}
function displayYear(p,e){return e.scene==='birth'?p.bornLabel||yearLabel(e.year):e.scene==='farewell'?p.diedLabel||yearLabel(e.year):yearLabel(e.year)}
function renderScene(){const {person:p,index}=game,e=p.events[index];stage.setScene(p,e,0);$('scenePlace').textContent=index===0?p.place:(p.region==='日本'?'日本':p.region)+' · '+eraLabel(p);$('sceneCounter').textContent=`第 ${index+1} 幕 / ${p.events.length}`;$('sceneYear').textContent=displayYear(p,e);$('sceneAge').textContent=ageAt(p,e);$('sceneChapter').textContent=`CHAPTER ${two(index+1)} · ${sceneNames[e.scene]||'人生'}`;$('sceneTitle').textContent=e.title;$('sceneText').textContent=e.text;const cap=$('sceneCaption');cap.classList.remove('enter');void cap.offsetWidth;cap.classList.add('enter');const tr=$('sceneTransition');tr.classList.remove('run');void tr.offsetWidth;tr.classList.add('run');$('timelineProgress').innerHTML=p.events.map((_,i)=>`<button class="progress-part" data-i="${i}" aria-label="第${i+1}幕${i>Math.floor(game.maxProgress*p.events.length)?' 未再生':''}" ${i>Math.max(index,Math.floor(game.maxProgress*p.events.length))?'disabled':''}><i></i></button>`).join('');$('timelineProgress').querySelectorAll('button').forEach(b=>b.onclick=()=>jump(Number(b.dataset.i)));$('prevBtn').disabled=index===0;updateProgress();tone();setTimeout(()=>{if(currentView==='theater'&&!game.paused)speak()},300)}
function eraLabel(p){return eras.find(e=>e.id===eraOf(p)).label+'生まれ'}
function jump(index){if(!game||index<0||index>=game.person.events.length)return;game.index=index;game.elapsed=0;game.maxProgress=Math.max(game.maxProgress,index/game.person.events.length);renderScene()}
function next(){if(!game)return;game.maxProgress=Math.max(game.maxProgress,(game.index+1)/game.person.events.length);if(game.index>=game.person.events.length-1){finish();return}jump(game.index+1)}
function updateProgress(){if(!game)return;const n=game.person.events.length;const nodes=$('timelineProgress').querySelectorAll('.progress-part');nodes.forEach((b,i)=>{b.firstElementChild.style.width=(i<game.index?100:i===game.index?game.elapsed/DURATION*100:0)+'%';if(i<=Math.floor(game.maxProgress*n))b.disabled=false});const sec=Math.min(n*DURATION,game.index*DURATION+game.elapsed);$('elapsedText').textContent=`${Math.floor(sec/60)}:${two(Math.floor(sec%60))}`;}
function openGuess(){if(!game||game.correct||currentView!=='theater')return;game.guessPaused=game.paused;setPaused(true);$('answerInput').value='';$('answerMessage').textContent='';$('answerChoices').hidden=!game.usedChoices;$('hintText').hidden=!game.hint;$('hintText').textContent=`手掛かり：主な分野は「${game.person.field}」。生まれた地域は${game.person.region}です。`;$('choicesBtn').innerHTML=game.usedChoices?'4択を表示中':'4択で答える <small>−100点</small>';$('hintBtn').innerHTML=game.hint?'ヒント表示中':'ヒント <small>−80点</small>';renderChoices();updateGuessScore();$('guessDialog').showModal();/* No autofocus: leave room for four choices on a phone. */}
function updateGuessScore(){if(!game)return;$('guessScore').textContent=`いま正解すると ${calculateScore({progress:game.maxProgress,mistakes:game.mistakes,choices:game.usedChoices,hint:game.hint}).toLocaleString()} 点 · 誤答 ${game.mistakes} 回`}
function renderChoices(){$('answerChoices').innerHTML=game.options.map((p,i)=>`<button type="button" data-choice="${p.id}" class="${game.wrongNames.has(p.id)?'wrong':''}" ${game.wrongNames.has(p.id)?'disabled':''}>${esc(p.name)}</button>`).join('');$('answerChoices').querySelectorAll('button').forEach(b=>b.onclick=()=>submitAnswer(PEOPLE.find(p=>p.id===b.dataset.choice).name,b.dataset.choice))}
function closeGuess(){if($('guessDialog').open)$('guessDialog').close()}
function submitAnswer(answer,id=null){if(!game||game.correct)return;answer=answer.trim();if(!answer){$('answerMessage').textContent='名前を入力するか、4択を選んでください。';return}if(matchesAnswer(game.person,answer)){game.correct=true;game.answeredAt={index:game.index,progress:game.maxProgress};game.score=calculateScore({progress:game.maxProgress,mistakes:game.mistakes,choices:game.usedChoices,hint:game.hint});closeGuess();$('correctBanner').hidden=false;$('guessPrompt').textContent='正解。その名を見抜きました。';$('guessSub').textContent=`${game.score.toLocaleString()}点を獲得。物語は、まだ続きます。`;$('guessBtn').textContent='答え合わせへ →';$('guessBtn').onclick=()=>finish();tone('correct');notify('正解です！ この人生を最後まで観られます。');return}game.mistakes++;if(id)game.wrongNames.add(id);$('answerMessage').textContent='その人物ではないようです。もう少し、足跡をたどってみよう。';updateGuessScore();if(id)renderChoices();tone('wrong')}
function finish(){if(!game)return;closeGuess();setPaused(true);stopSpeech();if(!game.saved){stats=recordGame(stats,game);persist();updateCounts();game.saved=true}showResult(game.person,game)}
function cardPortrait(p){let skin=['tubman','parks','king','johnson','mandela'].includes(p.id)?'#9b725b':'#d6ad85';const dress=['heian','curie','writerjp','nurse','frida','designer','activist','teacher','victorian'].includes(p.look);return `<svg viewBox="0 0 120 150" aria-hidden="true"><ellipse cx="60" cy="146" rx="47" ry="13" fill="#0f2933" opacity=".6"/><path d="M31 92Q60 81 89 92L${dress?107:95} 150H${dress?13:25}Z" fill="${p.region==='日本'?'#7a8d77':'#8c9d8c'}"/><path d="M48 91L60 115 73 91" fill="#d3c3a0"/><rect x="52" y="73" width="16" height="24" rx="4" fill="${skin}"/><ellipse cx="60" cy="55" rx="26" ry="31" fill="${skin}"/><path d="M34 55V37Q40 13 64 22Q89 20 88 54L77 39 46 37Z" fill="#3e4644"/><circle cx="50" cy="56" r="2" fill="#3d4240"/><circle cx="70" cy="56" r="2" fill="#3d4240"/><path d="M54 70Q60 74 66 70" fill="none" stroke="#976f56" stroke-width="2"/>${p.look==='lincoln'?'<rect x="30" y="23" width="60" height="7" fill="#1a3039"/><rect x="40" y="0" width="40" height="26" fill="#1a3039"/>':''}${p.look==='frida'?'<path d="M44 46h32" stroke="#403a35" stroke-width="3"/><g fill="#ba7761"><circle cx="37" cy="28" r="8"/><circle cx="51" cy="22" r="8"/><circle cx="65" cy="21" r="8"/><circle cx="79" cy="27" r="8"/></g>':''}${p.look==='einstein'?'<path d="M29 44L23 29 38 32 37 14 52 22 60 7 69 21 83 13 83 30 99 28 91 48 80 34 61 28 43 35Z" fill="#c5c7af"/>':''}${p.look==='beret'?'<ellipse cx="60" cy="25" rx="33" ry="10" fill="#203740"/>':''}</svg>`}
function showResult(p,round=null){if(portrait)portrait.observer.disconnect();const result=round?round.correct?'LIFE IDENTIFIED':'A NEW LIFE DISCOVERED':'YOUR HISTORY COLLECTION';const r=stats.records[p.id];const rank=round?.correct?(round.score>=850?'歴史の名探偵':round.score>=650?'時代の読解者':round.score>=400?'人生の観察者':'物語の旅人'):'新たな人生との出会い';$('result').innerHTML=`<div class="result-top"><button id="resultHome" class="text-link">← ロビー</button><span class="eyebrow">${result}</span></div><div class="result-hero"><div class="portrait-frame"><canvas id="portraitCanvas" width="500" height="600" aria-label="${esc(p.name)}のイラスト"></canvas><div class="portrait-label">LIFE NO. ${two(PEOPLE.indexOf(p)+1)} · ${esc(p.field)}</div></div><div class="result-copy"><p class="eyebrow">THE NAME BEHIND THE STORY</p><h1>${esc(p.name)}</h1><p class="life-dates">${esc(lifeDates(p))}</p><p class="result-title"><span>✦</span> ${esc(p.title)}</p><p class="result-description">${esc(p.summary)}</p><div class="person-tags"><span>${esc(p.region)}</span><span>${eraLabel(p)}</span><span>${esc(p.field)}</span></div></div></div>${round?`<div class="score-panel"><div><small>今回のスコア</small><strong>${round.correct?round.score.toLocaleString():'—'}<em>${round.correct?'pt':'未正解'}</em></strong></div><div><small>プレーヤーの称号</small><strong class="label-value">${rank}</strong></div><div><small>正解した場面</small><strong>${round.correct?round.answeredAt.index+1:'—'}<em>/ ${p.events.length}幕</em></strong></div><div><small>ヒント / 誤答</small><strong class="label-value">${round.usedChoices||round.hint?'利用あり':'なし'} / ${round.mistakes}回</strong></div></div>`:`<div class="score-panel"><div><small>この人物の最高スコア</small><strong>${r?.best||'—'}<em>pt</em></strong></div><div><small>出会った回数</small><strong>${r?.seen||1}</strong></div><div><small>正解した回数</small><strong>${r?.correct||0}</strong></div><div><small>記録</small><strong class="label-value">発見済み</strong></div></div>`}<div class="result-actions"><button class="primary" id="anotherBtn">次の人生に出会う <span>↗</span></button><button class="secondary" id="watchAgainBtn">もう一度観る</button><button class="secondary" id="resultArchiveBtn">人物図鑑へ</button></div><section class="timeline-section"><div class="section-heading"><div><p class="eyebrow">A LIFE IN EIGHT CHAPTERS</p><h2>この人生の足跡</h2></div><p>年齢・一部の年次は概数</p></div><div class="life-timeline">${p.events.map(e=>`<article class="life-event"><time>${esc(displayYear(p,e))}</time><div><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p></div></article>`).join('')}</div><div class="source-note"><p>参考資料：<a href="${esc(p.source[1])}" target="_blank" rel="noopener noreferrer">${esc(p.source[0])} ↗</a></p>${p.note?`<p>${esc(p.note)}</p>`:''}<details><summary>物語・称号・演出について</summary><p>主要な出来事を8幕に圧縮した学習用のダイジェストです。人物の服装、背景、動作は創作したイメージで、実際の映像・肖像を再現したものではありません。称号はこのゲーム独自の紹介表現です。各人物の功績と限界の両方に触れ、伝承や不明な点は区別しています。</p><p>誕生年に基づく分類：古代＝499年以前、中世＝500〜1499年、近世＝1500〜1799年、19世紀＝1800〜1899年、20世紀＝1900年以降。便宜的な区分で、各地域の歴史区分と必ずしも一致しません。</p></details></div></section><div class="result-link-row"><button class="text-link" id="bottomArchiveBtn">人物図鑑を見る →</button><button class="text-link" id="bottomHomeBtn">ロビーへ戻る →</button></div>`;
  showView('result');portraitPerson=p;portrait=new TheaterStage($('portraitCanvas'));portrait.setScene(p,{scene:'journey',year:Math.min(p.died-1,p.born+43)},.55);portrait.frozen=true;$('resultHome').onclick=()=>showView('home');$('anotherBtn').onclick=()=>start();$('watchAgainBtn').onclick=()=>start(p);$('resultArchiveBtn').onclick=showArchive;$('bottomArchiveBtn').onclick=showArchive;$('bottomHomeBtn').onclick=()=>showView('home');}
function showArchive(){showView('archive');$('archive').innerHTML=`<div class="archive-heading"><div><p class="eyebrow">THE LIVES YOU HAVE MET</p><h1>人生の図書室</h1><p>出会った人物を、ここに。まだ見ぬ人生は、幕の向こう。</p></div><div class="archive-stat">${Object.keys(stats.records).length}<small>/ ${PEOPLE.length}</small></div></div><div class="archive-filters"><div class="region-tabs"><button data-ar="all" ${!archiveUnlocked?'class="selected"':''}>すべて</button><button data-ar="unlocked" ${archiveUnlocked?'class="selected"':''}>発見した人物</button></div><div><select id="archiveRegion" aria-label="図鑑の地域"><option value="all">日本と世界</option><option value="japan">日本</option><option value="world">世界</option></select> <select id="archiveEra" aria-label="図鑑の時代">${eras.map(e=>`<option value="${e.id}">${e.label}</option>`).join('')}</select></div></div><div class="archive-summary"><span>上映した人生 <b>${stats.games}</b></span><span>正解した人生 <b>${stats.correct}</b></span><span>最高記録 <b>${stats.best.toLocaleString()}</b></span></div><div class="archive-grid" id="archiveGrid"></div><div class="result-link-row"><button class="text-link" id="archiveHome">← ロビーへ</button><button class="text-link" id="archiveStart">新しい人生に出会う ↗</button></div>`;$('archiveRegion').value=archiveRegion;$('archiveEra').value=archiveEra;$('archiveRegion').onchange=e=>{archiveRegion=e.target.value;renderArchiveCards()};$('archiveEra').onchange=e=>{archiveEra=e.target.value;renderArchiveCards()};$('archive').querySelectorAll('[data-ar]').forEach(b=>b.onclick=()=>{archiveUnlocked=b.dataset.ar==='unlocked';$('archive').querySelectorAll('[data-ar]').forEach(x=>x.classList.toggle('selected',x===b));renderArchiveCards()});$('archiveHome').onclick=()=>showView('home');$('archiveStart').onclick=()=>start();renderArchiveCards()}
function renderArchiveCards(){const pool=filterPeople(archiveEra,archiveRegion).filter(p=>!archiveUnlocked||stats.records[p.id]);$('archiveGrid').innerHTML=pool.length?pool.map(p=>{const r=stats.records[p.id];return `<button class="archive-card" data-person="${p.id}" aria-label="${r?esc(p.name)+'の解説を開く':'未発見の物語を上映'}"><div class="card-art ${r?'':'locked'}"><span class="card-number">NO. ${two(PEOPLE.indexOf(p)+1)}</span>${r?cardPortrait(p):''}</div><div class="card-info"><strong>${r?esc(p.name):'まだ名のない人生'}</strong><small>${r?esc(p.field):p.region==='日本'?'日本の物語':'世界の物語'} · ${eras.find(e=>e.id===eraOf(p)).label}</small>${r?`<span class="card-best">${r.best?`BEST ${r.best} pt`:'発見済み'}</span>`:'<span class="card-best">上映して見つける ↗</span>'}</div></button>`}).join(''):'<p class="archive-empty">この時代には、まだ出会っていません。<br>新しい人生を観に行こう。</p>';$('archiveGrid').querySelectorAll('button').forEach(b=>b.onclick=()=>{const p=PEOPLE.find(x=>x.id===b.dataset.person);stats.records[p.id]?showResult(p):start(p)})}
function requestExit(dest='home'){if(currentView!=='theater'){if(dest==='archive')showArchive();else showView('home');return}game.exitWasPaused=game.paused;game.exitDestination=dest;setPaused(true);$('exitDialog').showModal()}
function openHelp(){if(game&&currentView==='theater'){game.helpWasPaused=game.paused;setPaused(true)}$('helpDialog').showModal()}
function init(){hero=new TheaterStage($('heroCanvas'),{hero:true});hero.setScene(PEOPLE.find(p=>p.id==='basho'),{scene:'journey',year:1689},.35);stage=new TheaterStage($('stageCanvas'));updateFilters();updateCounts();$('startBtn').onclick=()=>start();document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{region=b.dataset.region;if(!filterPeople(era,region).length)era='all';updateFilters()});$('archiveBtn').onclick=()=>requestExit('archive');document.querySelector('.brand').onclick=e=>{e.preventDefault();requestExit('home')};$('helpBtn').onclick=openHelp;$('rulesBtn').onclick=openHelp;$('closeHelp').onclick=()=>$('helpDialog').close();$('helpStart').onclick=()=>$('helpDialog').close();$('helpDialog').addEventListener('close',()=>{if(game&&currentView==='theater')setPaused(!!game.helpWasPaused)});$('exitBtn').onclick=()=>requestExit('home');$('cancelExit').onclick=()=>$('exitDialog').close();$('confirmExit').onclick=()=>{const dest=game.exitDestination;game.exiting=true;$('exitDialog').close();game=null;dest==='archive'?showArchive():showView('home')};$('exitDialog').addEventListener('close',()=>{if(game&&!game.exiting&&currentView==='theater')setPaused(!!game.exitWasPaused)});$('pauseBtn').onclick=()=>setPaused(!game.paused);$('prevBtn').onclick=()=>jump(game.index-1);$('nextBtn').onclick=next;$('speedSelect').onchange=e=>{speed=Number(e.target.value);if(narration)notify('朗読の速さは固定です。場面の送りは再生速度に従います。')};$('guessBtn').onclick=openGuess;$('revealNow').onclick=finish;$('guessForm').onsubmit=e=>{e.preventDefault();submitAnswer($('answerInput').value)};$('closeGuess').onclick=closeGuess;$('guessDialog').addEventListener('close',()=>{if(game&&currentView==='theater')setPaused(!!game.guessPaused)});$('choicesBtn').onclick=()=>{game.usedChoices=true;$('answerChoices').hidden=false;$('choicesBtn').textContent='4択を表示中';updateGuessScore()};$('hintBtn').onclick=()=>{game.hint=true;$('hintText').hidden=false;$('hintText').textContent=`手掛かり：主な分野は「${game.person.field}」。生まれた地域は${game.person.region}です。`;$('hintBtn').textContent='ヒント表示中';updateGuessScore()};$('soundBtn').onclick=async()=>{sound=!sound;if(sound){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)throw Error();audio ||=new A();await audio.resume();tone()}catch{sound=false;notify('この端末では音を再生できません。')}}$('soundBtn').setAttribute('aria-pressed',String(sound));$('soundBtn').setAttribute('aria-label',sound?'音をオフ':'音をオン');notify(sound?'音をオンにしました':'音をオフにしました')};$('narrateBtn').onclick=()=>{if(!window.speechSynthesis){notify('この端末では朗読を利用できません。');return}narration=!narration;$('narrateBtn').setAttribute('aria-pressed',String(narration));$('narrateBtn').setAttribute('aria-label',narration?'朗読をオフ':'朗読をオン');if(narration)speak();else stopSpeech();notify(narration?'朗読をオンにしました':'朗読をオフにしました')};document.addEventListener('visibilitychange',()=>{if(document.hidden&&currentView==='theater'&&game&&!game.paused)setPaused(true);if(document.hidden)stopSpeech()});document.addEventListener('keydown',e=>{if(currentView!=='theater'||document.querySelector('dialog[open]')||['INPUT','SELECT'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();setPaused(!game.paused)}else if(e.key==='Enter'){e.preventDefault();openGuess()}else if(e.key==='ArrowRight'){e.preventDefault();next()}});window.addEventListener('pagehide',stopSpeech);requestAnimationFrame(tick);}
function tick(now){const dt=Math.min(.07,(now-(lastFrame||now))/1000);lastFrame=now;if(!document.hidden){if(currentView==='home'){heroClock+=dt;if(heroClock>=14){heroClock=0;heroIndex=(heroIndex+1)%3;const hs=[['basho','journey',1689],['curie','laboratory',1898],['beethoven','music',1824]][heroIndex];hero.setScene(PEOPLE.find(p=>p.id===hs[0]),{scene:hs[1],year:hs[2]},.4)}hero.progress=.25+heroClock/28;hero.render(dt)}if(currentView==='theater'&&game){if(!game.paused){game.elapsed+=dt*speed;game.maxProgress=Math.max(game.maxProgress,(game.index+game.elapsed/DURATION)/game.person.events.length);stage.progress=game.elapsed/DURATION;ambientClock+=dt;if(ambientClock>6){tone('scene');ambientClock=0}if(game.elapsed>=DURATION){next();if(currentView!=='theater'){requestAnimationFrame(tick);return}}updateProgress()}stage.render(dt)}if(currentView==='result'&&portrait){portrait.render(0)}}requestAnimationFrame(tick)}
init();
